custom_css:
.sc-tw :root{
            color-scheme: dark;
            --bg: oklch(12% 0.05 30);
            --bg2: oklch(15% 0.04 30);
            --charcoal: oklch(18% 0.03 30);
            --ochre: oklch(76% 0.14 68);
            --cheddar: oklch(72% 0.17 54);
            --jalapeno: oklch(67% 0.14 145);
            --ink: oklch(97% 0.01 30);
            --muted: rgba(255, 255, 255, .66);
        }.sc-tw *{
            box-sizing: border-box;
        }.sc-tw html{
            scroll-behavior: smooth;
        }.sc-tw{
            margin: 0;
            overflow-x: hidden;
            font-family: "Inter Tight", sans-serif;
            background:
                radial-gradient(circle at 18% 10%, rgba(222, 141, 57, .13), transparent 16%),
                radial-gradient(circle at 82% 14%, rgba(90, 176, 84, .08), transparent 14%),
                linear-gradient(180deg, oklch(12% 0.05 30) 0%, oklch(10% 0.045 30) 48%, oklch(8% 0.04 30) 100%);
            color: white;
        }.sc-tw body::before{
            content: "";
            position: fixed;
            inset: 0;
            pointer-events: none;
            background-image:
                linear-gradient(rgba(255, 255, 255, .03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255, 255, 255, .03) 1px, transparent 1px),
                linear-gradient(135deg, transparent 0 48%, rgba(255, 255, 255, .025) 48% 52%, transparent 52%);
            background-size: 120px 120px, 120px 120px, 280px 280px;
            opacity: .22;
            z-index: -2;
        }.sc-tw .display{
            font-family: "Fraunces", serif;
            letter-spacing: -.06em;
        }.sc-tw .copy{
            font-family: "Inter Tight", sans-serif;
        }.sc-tw .smoked{
            background: rgba(255, 255, 255, .06);
            border: 1px solid rgba(255, 255, 255, .09);
            backdrop-filter: blur(20px) contrast(.95);
            -webkit-backdrop-filter: blur(20px) contrast(.95);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .08),
                0 18px 60px rgba(0, 0, 0, .35);
        }.sc-tw .textured-touch{
            position: relative;
            overflow: hidden;
            border-radius: 1rem;
            background:
                linear-gradient(180deg, rgba(227, 178, 104, .88), rgba(183, 122, 59, .82)),
                linear-gradient(135deg, rgba(255, 255, 255, .08), transparent 45%);
            border: 1px solid rgba(255, 255, 255, .12);
            color: #1c140d;
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .4),
                inset 0 -12px 18px rgba(0, 0, 0, .08),
                0 20px 48px rgba(0, 0, 0, .3);
            transition: transform .45s cubic-bezier(.16, 1, .3, 1), box-shadow .45s ease;
        }.sc-tw .textured-touch::before{
            content: "";
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(135deg, rgba(0, 0, 0, .12) 0 1px, transparent 1px 100%),
                linear-gradient(45deg, rgba(0, 0, 0, .06) 0 1px, transparent 1px 100%);
            opacity: .28;
            pointer-events: none;
            mix-blend-mode: multiply;
        }.sc-tw .textured-touch::after{
            content: "";
            position: absolute;
            inset: -110%;
            background:
                radial-gradient(circle at 30% 40%, rgba(255, 255, 255, .35), transparent 16%),
                radial-gradient(circle at 55% 60%, rgba(255, 255, 255, .18), transparent 20%),
                linear-gradient(120deg, transparent 44%, rgba(255, 255, 255, .72) 50%, transparent 56%);
            transform: translateX(-140%) rotate(12deg);
            animation: sheen 8s ease-in-out infinite;
            pointer-events: none;
            mix-blend-mode: screen;
            filter: blur(.2px);
        }.sc-tw .textured-touch:hover{
            transform: translateY(-4px);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .48),
                inset 0 -12px 18px rgba(0, 0, 0, .08),
                0 28px 56px rgba(0, 0, 0, .36);
        }.sc-tw .textured-touch:active{
            transform: translateY(1px) scale(.99);
        }.sc-tw .sizzle{
            position: relative;
            overflow: hidden;
            border-radius: 1rem;
            background: linear-gradient(180deg, rgba(235, 170, 84, .24), rgba(255, 255, 255, .06));
            border: 1px solid rgba(235, 170, 84, .24);
            color: white;
            backdrop-filter: blur(20px) contrast(.95);
            -webkit-backdrop-filter: blur(20px) contrast(.95);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .08),
                0 20px 48px rgba(0, 0, 0, .34);
            transition: transform .45s cubic-bezier(.16, 1, .3, 1), box-shadow .45s ease, border-color .35s ease;
        }.sc-tw .sizzle::before{
            content: "";
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at 20% 30%, rgba(255, 255, 255, .18), transparent 12%),
                radial-gradient(circle at 70% 68%, rgba(255, 255, 255, .12), transparent 10%),
                radial-gradient(circle at 55% 45%, rgba(255, 255, 255, .14), transparent 10%);
            opacity: 0;
            transform: scale(.9);
            transition: .5s ease;
            pointer-events: none;
        }.sc-tw .sizzle::after{
            content: "";
            position: absolute;
            inset: -100%;
            background:
                linear-gradient(120deg, transparent 46%, rgba(255, 255, 255, .58) 50%, transparent 54%);
            transform: translateX(-130%) rotate(10deg);
            animation: sheen 9s ease-in-out infinite;
            pointer-events: none;
            mix-blend-mode: screen;
        }.sc-tw .sizzle:hover{
            transform: translateY(-4px);
            border-color: rgba(235, 170, 84, .4);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .08),
                0 26px 60px rgba(0, 0, 0, .42),
                0 0 0 1px rgba(235, 170, 84, .12);
        }.sc-tw .sizzle:hover::before{
            opacity: 1;
            transform: scale(1.2);
        }.sc-tw .slat-bar{
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            z-index: 80;
            background: rgba(10, 10, 10, .74);
            border-bottom: 1px solid rgba(255, 255, 255, .08);
            backdrop-filter: blur(14px) contrast(.96);
            -webkit-backdrop-filter: blur(14px) contrast(.96);
        }.sc-tw .slat-inner{
            width: min(1600px, calc(100% - 32px));
            margin: 0 auto;
            display: grid;
            grid-template-columns: 1.1fr 1.1fr .8fr;
            gap: 18px;
            align-items: stretch;
            padding: 16px 0;
        }.sc-tw .slat-brand,.sc-tw .slat-nav,.sc-tw .slat-action{
            min-height: 58px;
            border: 1px solid rgba(255, 255, 255, .08);
            background: rgba(255, 255, 255, .04);
            display: flex;
            align-items: center;
            padding: 0 18px;
        }.sc-tw .slat-brand{
            justify-content: flex-start;
            gap: 14px;
        }.sc-tw .brand-mark{
            width: 38px;
            height: 38px;
            border-radius: 12px;
            display: grid;
            place-items: center;
            background: rgba(255, 255, 255, .08);
            border: 1px solid rgba(255, 255, 255, .08);
        }.sc-tw .slat-nav{
            justify-content: center;
            gap: 18px;
            text-transform: uppercase;
            letter-spacing: .26em;
            font-size: 10px;
            color: rgba(255, 255, 255, .62);
            overflow-x: auto;
            scrollbar-width: none;
        }.sc-tw .slat-nav::-webkit-scrollbar{
            display: none;
        }.sc-tw .slat-nav a{
            color: inherit;
            text-decoration: none;
            white-space: nowrap;
            transition: .25s ease;
        }.sc-tw .slat-nav a:hover{
            color: #f2b965;
        }.sc-tw .slat-action{
            justify-content: flex-end;
            gap: 12px;
        }.sc-tw .mini-meter{
            width: 100%;
            max-width: 220px;
            height: 8px;
            background: rgba(255, 255, 255, .08);
            overflow: hidden;
        }.sc-tw .mini-meter span{
            display: block;
            width: 72%;
            height: 100%;
            background: linear-gradient(90deg, rgba(237, 176, 84, .86), rgba(255, 232, 181, .95));
        }.sc-tw .hero{
            position: relative;
            min-height: 100svh;
            background: var(--bg);
            overflow: hidden;
        }.sc-tw .hero-grid{
            position: relative;
            z-index: 4;
            width: min(1600px, calc(100% - 32px));
            margin: 0 auto;
            min-height: 100svh;
            display: grid;
            grid-template-columns: .4fr .6fr;
            gap: 0;
            padding-top: 110px;
        }.sc-tw .hero-copy{
            position: relative;
            z-index: 30;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 56px 22px 56px 0;
        }.sc-tw .hero-copy-inner{
            width: 100%;
            max-width: 560px;
            padding: 28px 28px 32px;
            background: rgba(14, 14, 14, .44);
            border: 1px solid rgba(255, 255, 255, .08);
            backdrop-filter: blur(20px) contrast(.95);
            -webkit-backdrop-filter: blur(20px) contrast(.95);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .08),
                0 24px 60px rgba(0, 0, 0, .38);
        }.sc-tw .hero-kicker{
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 10px 14px;
            background: rgba(255, 255, 255, .06);
            border: 1px solid rgba(255, 255, 255, .08);
            text-transform: uppercase;
            letter-spacing: .28em;
            font-size: 10px;
            color: rgba(255, 255, 255, .7);
        }.sc-tw .hero-kicker span{
            width: 8px;
            height: 8px;
            background: var(--ochre);
            display: inline-block;
        }.sc-tw .hero-title{
            margin-top: 22px;
            font-size: clamp(4.2rem, 10vw, 8.6rem);
            line-height: .82;
            letter-spacing: -.08em;
            color: white;
            text-shadow:
                0 8px 20px rgba(0, 0, 0, .22),
                0 0 20px rgba(235, 170, 84, .06);
        }.sc-tw .heat-wave{
            display: inline-block;
            animation: heatWave 6.5s ease-in-out infinite;
            transform-origin: left center;
        }.sc-tw .hero-text{
            margin-top: 20px;
            color: rgba(255, 255, 255, .82);
            font-family: "PP Neue Montreal", "Inter Tight", sans-serif;
            line-height: 1.95;
            font-size: 16px;
        }.sc-tw .specs{
            margin-top: 22px;
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
        }.sc-tw .specs span{
            padding: 10px 12px;
            background: rgba(255, 255, 255, .06);
            border: 1px solid rgba(255, 255, 255, .08);
            text-transform: uppercase;
            letter-spacing: .2em;
            font-size: 10px;
            color: rgba(255, 255, 255, .72);
        }.sc-tw .hero-cta{
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
            margin-top: 26px;
        }.sc-tw .hero-cta button{
            height: 54px;
            padding: 0 20px;
            border: none;
            cursor: pointer;
            font-size: 10px;
            letter-spacing: .28em;
            text-transform: uppercase;
        }.sc-tw .sizzle-wrap{
            display: inline-flex;
            align-items: center;
            gap: 10px;
        }.sc-tw .hero-visual{
            position: relative;
            min-height: 100svh;
            overflow: hidden;
            z-index: 10;
        }.sc-tw .splash-shell{
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);

            width: 120%;
            height: 110%;

            display: flex;
            align-items: center;
            justify-content: center;
        }.sc-tw .splash-shell video{
            width: 100%;
            height: 100%;
            object-fit: contain;
            object-position: center;
        }.sc-tw .mask-edge{
            -webkit-mask-image: linear-gradient(to right,
                    transparent 0%,
                    black 15%,
                    black 70%,
                    transparent 90%);
            mask-image: linear-gradient(to right,
                    transparent 0%,
                    black 15%,
                    black 70%,
                    transparent 90%);
        }.sc-tw .sauce-glow{
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at 18% 26%, rgba(0, 0, 0, 0.28), transparent 18%),
                radial-gradient(circle at 52% 24%, rgba(255, 228, 195, .12), transparent 16%),
                radial-gradient(circle at 70% 62%, rgba(110, 208, 76, .16), transparent 16%),
                linear-gradient(180deg, rgba(0, 37, 32, 0.08), rgba(0, 0, 0, .4));
            pointer-events: none;
        }.sc-tw .ingredient-field{
            position: absolute;
            inset: 0;
            z-index: 22;
            pointer-events: none;
            overflow: hidden;
        }.sc-tw .seed,.sc-tw .drip{
            position: absolute;
            background: rgba(255, 242, 216, .9);
            transform-origin: center;
            filter: drop-shadow(0 0 8px rgba(255, 193, 85, .12));
            animation: flight 10s linear infinite;
        }.sc-tw .seed{
            width: 10px;
            height: 4px;
            border-radius: 2px;
        }.sc-tw .drip{
            width: 18px;
            height: 6px;
            border-radius: 2px;
            background: rgba(255, 126, 40, .9);
        }.sc-tw .heat-scrim{
            position: absolute;
            left: 0;
            top: 0;
            bottom: 0;
            width: 42%;
            z-index: 28;
            background:
                linear-gradient(90deg, rgba(12, 12, 12, .64), rgba(12, 12, 12, .32) 55%, transparent 100%);
            pointer-events: none;
        }.sc-tw .section{
            padding: 120px 0;
        }.sc-tw .shell{
            width: min(1600px, calc(100% - 32px));
            margin: 0 auto;
        }.sc-tw .ledger{
            position: relative;
            padding: 32px 0 8px;
        }.sc-tw .ledger::before{
            content: "";
            position: absolute;
            left: 0;
            right: 0;
            top: 0;
            height: 1px;
            background: linear-gradient(90deg, transparent, rgba(255, 153, 60, .35), rgba(118, 204, 86, .24), transparent);
        }.sc-tw .ledger-head{
            display: flex;
            justify-content: space-between;
            gap: 24px;
            align-items: flex-end;
            margin-bottom: 26px;
        }.sc-tw .ledger-head h2{
            font-size: clamp(2.8rem, 5.7vw, 6rem);
            line-height: .88;
            letter-spacing: -.07em;
            color: white;
        }.sc-tw .ledger-head p{
            max-width: 420px;
            line-height: 1.95;
            color: rgba(255, 255, 255, .66);
        }.sc-tw .assemble{
            opacity: 0;
            transform: translateY(30px);
            animation: assembleIn .9s cubic-bezier(.16, 1, .3, 1) forwards;
            animation-timeline: view();
            animation-range: entry 12% cover 32%;
        }.sc-tw .strip{
            display: grid;
            grid-template-columns: .9fr 1.1fr .4fr;
            gap: 18px;
            align-items: end;
            padding: 22px 0;
            border-top: 1px solid rgba(255, 255, 255, .09);
            border-bottom: 1px solid rgba(255, 255, 255, .05);
            position: relative;
            overflow: hidden;
        }.sc-tw .strip::before{
            content: "";
            position: absolute;
            inset: 0;
            background:
                linear-gradient(90deg, rgba(255, 153, 60, .08), transparent 35%, rgba(118, 204, 86, .06) 75%, transparent 100%);
            opacity: .55;
            pointer-events: none;
        }.sc-tw .strip:nth-child(2){
            margin-left: 6%;
            width: 88%;
        }.sc-tw .strip:nth-child(3){
            margin-left: 11%;
            width: 82%;
        }.sc-tw .strip:nth-child(4){
            margin-left: 4%;
            width: 92%;
        }.sc-tw .strip .label{
            text-transform: uppercase;
            letter-spacing: .3em;
            font-size: 10px;
            color: rgba(255, 255, 255, .55);
        }.sc-tw .strip h3{
            margin-top: 12px;
            font-size: clamp(1.8rem, 3.2vw, 3.4rem);
            line-height: .94;
            letter-spacing: -.05em;
            color: white;
        }.sc-tw .strip p{
            margin-top: 16px;
            max-width: 48ch;
            line-height: 1.9;
            color: rgba(255, 255, 255, .68);
        }.sc-tw .strip .metric{
            justify-self: end;
            font-size: clamp(3rem, 6vw, 5.4rem);
            line-height: 1;
            letter-spacing: -.08em;
            color: rgba(255, 255, 255, .14);
        }.sc-tw .text-stack{
            padding: 120px 0;
            background:
                radial-gradient(circle at 18% 18%, rgba(255, 153, 60, .09), transparent 18%),
                radial-gradient(circle at 84% 28%, rgba(118, 204, 86, .08), transparent 16%),
                linear-gradient(180deg, rgba(17, 17, 17, .55), rgba(8, 8, 8, .92));
        }.sc-tw .text-stack-shell{
            width: min(1600px, calc(100% - 32px));
            margin: 0 auto;
            display: grid;
            grid-template-columns: 1.05fr .95fr;
            gap: 24px;
            align-items: start;
        }.sc-tw .recipe-wall{
            padding: 48px;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, .025)),
                linear-gradient(135deg, rgba(255, 255, 255, .035), transparent 42%);
            border: 1px solid rgba(255, 255, 255, .08);
            box-shadow: 0 24px 80px rgba(0, 0, 0, .34);
        }.sc-tw .recipe-wall h2{
            font-size: clamp(3rem, 6vw, 6rem);
            line-height: .88;
            letter-spacing: -.07em;
            color: white;
        }.sc-tw .recipe-wall p{
            margin-top: 18px;
            max-width: 680px;
            line-height: 2;
            color: rgba(255, 255, 255, .68);
            font-family: "PP Neue Montreal", "Inter Tight", sans-serif;
            font-size: 16px;
        }.sc-tw .layer-rail{
            position: relative;
            display: flex;
            flex-direction: column;
            gap: 16px;
            padding-top: 14px;
        }.sc-tw .layer{
            min-height: 128px;
            padding: 20px 22px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .08), rgba(255, 255, 255, .03)),
                linear-gradient(135deg, rgba(255, 255, 255, .05), transparent 65%);
            border: 1px solid rgba(255, 255, 255, .07);
            box-shadow: 0 18px 44px rgba(0, 0, 0, .24);
            transform: translateX(0);
            transition: transform .45s cubic-bezier(.16, 1, .3, 1), opacity .45s ease;
            opacity: 0;
        }.sc-tw .layer:nth-child(2){
            margin-left: 6%;
        }.sc-tw .layer:nth-child(3){
            margin-left: 12%;
        }.sc-tw .layer:nth-child(4){
            margin-left: 4%;
        }.sc-tw .layer.in{
            opacity: 1;
        }.sc-tw .layer .top{
            display: flex;
            justify-content: space-between;
            gap: 18px;
            align-items: flex-start;
        }.sc-tw .layer .tag{
            text-transform: uppercase;
            letter-spacing: .28em;
            font-size: 10px;
            color: rgba(255, 255, 255, .55);
        }.sc-tw .layer .name{
            font-size: clamp(1.5rem, 2.8vw, 2.7rem);
            line-height: .95;
            letter-spacing: -.05em;
            color: white;
        }.sc-tw .layer .bar{
            height: 8px;
            background: rgba(255, 255, 255, .08);
            overflow: hidden;
            margin-top: 12px;
        }.sc-tw .layer .bar span{
            display: block;
            height: 100%;
            width: var(--w, 70%);
            background: linear-gradient(90deg, rgba(255, 153, 60, .75), rgba(118, 204, 86, .75));
        }.sc-tw .counter{
            margin-top: 20px;
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
        }.sc-tw .counter span{
            padding: 10px 12px;
            background: rgba(255, 255, 255, .06);
            border: 1px solid rgba(255, 255, 255, .08);
            text-transform: uppercase;
            letter-spacing: .2em;
            font-size: 10px;
            color: rgba(255, 255, 255, .7);
        }.sc-tw .finish{
            padding: 120px 0 110px;
        }.sc-tw .finish-shell{
            width: min(1600px, calc(100% - 32px));
            margin: 0 auto;
            display: grid;
            grid-template-columns: 1.2fr .8fr;
            gap: 24px;
            align-items: stretch;
        }.sc-tw .menu-board{
            padding: 56px;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .065), rgba(255, 255, 255, .02)),
                linear-gradient(135deg, rgba(235, 170, 84, .08), transparent 35%, rgba(118, 204, 86, .06) 75%);
            border: 1px solid rgba(255, 255, 255, .08);
            box-shadow: 0 22px 70px rgba(0, 0, 0, .34);
        }.sc-tw .menu-board h2{
            font-size: clamp(3rem, 6vw, 6rem);
            line-height: .88;
            letter-spacing: -.07em;
            color: white;
        }.sc-tw .menu-board p{
            margin-top: 18px;
            max-width: 740px;
            color: rgba(255, 255, 255, .68);
            line-height: 2;
            font-family: "PP Neue Montreal", "Inter Tight", sans-serif;
        }.sc-tw .board-actions{
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
            margin-top: 28px;
        }.sc-tw .info-stack{
            display: flex;
            flex-direction: column;
            gap: 16px;
        }.sc-tw .info{
            min-height: 160px;
            padding: 24px;
            background: rgba(255, 255, 255, .05);
            border: 1px solid rgba(255, 255, 255, .08);
            box-shadow: 0 18px 44px rgba(0, 0, 0, .24);
        }.sc-tw .info .label{
            text-transform: uppercase;
            letter-spacing: .28em;
            font-size: 10px;
            color: rgba(255, 255, 255, .52);
        }.sc-tw .info .value{
            margin-top: 16px;
            font-size: clamp(2.4rem, 4vw, 4.2rem);
            line-height: .92;
            letter-spacing: -.06em;
            color: white;
        }.sc-tw .footer-line{
            margin-top: 28px;
            height: 1px;
            background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .22), transparent);
        }.sc-tw .foot{
            padding: 0 0 84px;
        }.sc-tw .foot-shell{
            width: min(1600px, calc(100% - 32px));
            margin: 0 auto;
            padding: 28px 32px 34px;
            background: rgba(255, 255, 255, .035);
            border: 1px solid rgba(255, 255, 255, .08);
            box-shadow: 0 22px 70px rgba(0, 0, 0, .22);
        }.sc-tw .foot-grid{
            display: flex;
            justify-content: space-between;
            gap: 24px;
            align-items: flex-end;
            flex-wrap: wrap;
        }.sc-tw .foot-grid .left{
            max-width: 760px;
        }.sc-tw .foot-grid h3{
            font-size: clamp(2.2rem, 4vw, 4.6rem);
            line-height: .92;
            letter-spacing: -.06em;
            color: white;
        }.sc-tw .foot-grid p{
            margin-top: 16px;
            color: rgba(255, 255, 255, .68);
            line-height: 1.95;
        }.sc-tw .tags{
            display: flex;
            flex-wrap: wrap;
            gap: 12px;
            justify-content: flex-end;
        }.sc-tw .tags span{
            padding: 10px 12px;
            background: rgba(255, 255, 255, .06);
            border: 1px solid rgba(255, 255, 255, .08);
            text-transform: uppercase;
